package com.enterprise.mq.consumer;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

public class TaskQueueConsumer {

    enum Role { ADMIN, OPERATOR, VIEWER }

    static class UserSession {
        String userId;
        Role role;
        String hmacToken;
        long timestamp;

        UserSession(String userId, Role role, String hmacToken, long timestamp) {
            this.userId = userId;
            this.role = role;
            this.hmacToken = hmacToken;
            this.timestamp = timestamp;
        }
    }

    static class TaskMessage {
        String messageId;
        String userId;
        String command;
        Map<String, String> parameters;
        String signature;

        TaskMessage(String messageId, String userId, String command,
                    Map<String, String> parameters, String signature) {
            this.messageId = messageId;
            this.userId = userId;
            this.command = command;
            this.parameters = parameters;
            this.signature = signature;
        }
    }

    private static final String HMAC_SECRET = "s3cr3t_k3y_2024";
    private static final Set<String> ALLOWED_COMMANDS = Set.of(
        "generate-report", "export-data", "run-diagnostics", "backup-config"
    );
    private static final Set<String> ADMIN_ONLY_COMMANDS = Set.of(
        "run-diagnostics", "backup-config"
    );

    private final ConcurrentHashMap<String, UserSession> sessionStore = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(4);

    public void registerSession(String userId, Role role) {
        String token = generateHmac(userId + ":" + role.name() + ":" + System.currentTimeMillis());
        sessionStore.put(userId, new UserSession(userId, role, token, System.currentTimeMillis()));
    }

    public void consumeMessage(TaskMessage message) {
        // Step 1: Validate message signature
        if (!verifyMessageSignature(message)) {
            logSecurityEvent("Invalid signature for message: " + message.messageId);
            return;
        }

        // Step 2: Verify user session exists
        UserSession session = sessionStore.get(message.userId);
        if (session == null) {
            logSecurityEvent("No active session for user: " + message.userId);
            return;
        }

        // Step 3: Check session freshness (30 minute window)
        if (System.currentTimeMillis() - session.timestamp > 1800000) {
            logSecurityEvent("Expired session for user: " + message.userId);
            sessionStore.remove(message.userId);
            return;
        }

        // Step 4: Validate command is in allowlist
        if (!ALLOWED_COMMANDS.contains(message.command)) {
            logSecurityEvent("Disallowed command: " + message.command);
            return;
        }

        // Step 5: Role-based access control
        if (ADMIN_ONLY_COMMANDS.contains(message.command) && session.role != Role.ADMIN) {
            logSecurityEvent("Unauthorized access attempt by: " + message.userId);
            return;
        }

        // Step 6: Execute the validated command
        executor.submit(() -> executeTask(message.command, message.parameters, session));
    }

    private void executeTask(String command, Map<String, String> parameters, UserSession session) {
        try {
            String taskScript = resolveTaskScript(command);
            String[] cmdArray = buildCommandArray(taskScript, parameters, session);
            ProcessBuilder pb = new ProcessBuilder(cmdArray);
            pb.redirectErrorStream(true);
            Process process = pb.start();
            process.waitFor(60, TimeUnit.SECONDS);
        } catch (Exception e) {
            logSecurityEvent("Task execution failed: " + e.getMessage());
        }
    }

    private String resolveTaskScript(String command) {
        // Maps validated command names to script paths
        Map<String, String> scriptMap = Map.of(
            "generate-report", "/opt/tasks/report_gen.sh",
            "export-data", "/opt/tasks/data_export.sh",
            "run-diagnostics", "/opt/tasks/diagnostics.sh",
            "backup-config", "/opt/tasks/backup.sh"
        );
        return scriptMap.getOrDefault(command, "/opt/tasks/noop.sh");
    }

    private String[] buildCommandArray(String script, Map<String, String> parameters, UserSession session) {
        List<String> cmd = new ArrayList<>();
        cmd.add("/bin/bash");
        cmd.add(script);

        // Add sanitized parameters
        String outputFormat = sanitizeParam(parameters.getOrDefault("format", "json"));
        String targetScope = sanitizeParam(parameters.getOrDefault("scope", "default"));
        cmd.add("--format=" + outputFormat);
        cmd.add("--scope=" + targetScope);
        cmd.add("--user=" + sanitizeParam(session.userId));

        // Admin users can specify custom output path for flexibility
        if (session.role == Role.ADMIN && parameters.containsKey("outputPath")) {
            cmd.add("--output=" + parameters.get("outputPath"));
        }

        return cmd.toArray(new String[0]);
    }

    private String sanitizeParam(String input) {
        if (input == null) return "";
        // Remove shell metacharacters
        return input.replaceAll("[^a-zA-Z0-9._\\-/]", "");
    }

    private boolean verifyMessageSignature(TaskMessage message) {
        String payload = message.messageId + ":" + message.userId + ":" + message.command;
        String expected = generateHmac(payload);
        return MessageDigest.isEqual(
            expected.getBytes(StandardCharsets.UTF_8),
            message.signature.getBytes(StandardCharsets.UTF_8)
        );
    }

    private String generateHmac(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(HMAC_SECRET.getBytes(StandardCharsets.UTF_8));
            byte[] hash = md.digest(data.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString();
        } catch (Exception e) {
            return "";
        }
    }

    private void logSecurityEvent(String event) {
        System.err.println("[SECURITY] " + new Date() + " - " + event);
    }
}
